<?php declare(strict_types=1);$a=$data['access'];$profile=$a['profile'];$assignedW=array_flip($a['assignedWarehouseIds']);$assignedL=array_flip($a['assignedLocationIds']);?>
<div class="module-stack"><nav class="card"><a class="btn btn-secondary btn-compact" href="<?=e(appBasePath())?>/administration/users/view?id=<?=e($profile['user_id'])?>">Back to user</a></nav><header class="page-header"><div><p class="eyebrow">Operational inventory authorization</p><h1><?=e($profile['display_name'])?></h1><p>Warehouse management permission is not granted here. These assignments authorize day-to-day warehouse/location use only.</p></div></header><?php if(!empty($data['notice'])):?><div class="notice success"><?=e($data['notice']['message'])?></div><?php endif;?><?php foreach(($data['errors']??[]) as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><?php if(!empty($a['implicitAllAccess'])):?><div class="alert alert-warning">Company Owner / system administrator has implicit operational access to every active operational source. Saved assignments are retained for future role changes.</div><?php endif;?><form class="card" method="post" action="<?=e(appBasePath())?>/administration/users/inventory-access"><?=csrfField()?><input type="hidden" name="user_id" value="<?=e($profile['user_id'])?>"><?php foreach($a['warehouses'] as $w):?><fieldset><legend><label><input type="checkbox" name="warehouse_ids[]" value="<?=e($w['warehouse_id'])?>" <?=isset($assignedW[(int)$w['warehouse_id']])?'checked':''?> <?=empty($w['active'])?'disabled':''?>> <?=e($w['code'].' - '.$w['name'])?><?=empty($w['active'])?' (inactive)':''?></label></legend><?php foreach($a['locations'] as $l):if((int)$l['warehouse_id']!==(int)$w['warehouse_id'])continue;$operational=!empty($l['active'])&&!empty($l['picking_allowed'])&&($l['location_usage']??'')==='internal'&&empty($l['is_virtual']);?><label><input type="checkbox" name="location_ids[]" value="<?=e($l['location_id'])?>" <?=isset($assignedL[(int)$l['location_id']])?'checked':''?> <?=$operational?'':'disabled'?>> <?=e($l['code'].' - '.$l['name'])?><?=$operational?'':' (not an active picking source)'?></label><?php endforeach;?></fieldset><?php endforeach;?><button class="btn btn-primary">Save operational access</button></form></div>
